# owner: platform
import unittest

from hourglass.rounding import (
    round_span,
    rounded_labels,
    span_label,
)
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundTests(unittest.TestCase):
    # ---
    def test_snaps_to_nearest(self):
        span = parse_span("09:07-17:08")
        self.assertEqual(
            round_span(span, 15), parse_span("09:00-17:15")
        )

    # ---
    def test_halfway_rounds_up(self):
        span = parse_span("09:05-17:35")
        self.assertEqual(
            round_span(span, 10), parse_span("09:10-17:40")
        )

    # ---
    def test_hour_step(self):
        span = parse_span("08:31-16:29")
        self.assertEqual(
            round_span(span, 60), parse_span("09:00-16:00")
        )

    # ---
    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(parse_span("09:02-09:05"), 15)

class StepTests(unittest.TestCase):
    # ---
    def test_bad_steps_raise(self):
        spans = [parse_span("09:00-10:00")]
        for step in (0, -5, 7, 45, 90):
            with self.assertRaises(ValueError):
                rounded_labels(spans, step)

    # ---
    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

class LabelTests(unittest.TestCase):
    # ---
    def test_label(self):
        span = parse_span("09:00-17:15")
        self.assertEqual(
            span_label(span), "09:00-17:15 (8h 15m)"
        )

    # ---
    def test_rounded_labels(self):
        spans = [parse_span("09:02-17:13")]
        spans.append(parse_span("18:00-18:45"))
        want = ["09:00-17:15 (8h 15m)"]
        want.append("18:00-18:45 (0h 45m)")
        self.assertEqual(rounded_labels(spans, 15), want)

    # ---
    def test_end_of_day(self):
        label = rounded_labels([Span(1400, 1439)], 5)
        self.assertEqual(label, ["23:20-24:00 (0h 40m)"])
